/*
 * A141326  Subsequence of 'Fermat near misses' which is generated by a simple
 *          formula based on the cubic binomial expansion along with formulas
 *          for the corresponding terms in the expression, x^3 + y^3 = z^3 +
 *          1.
 * https://oeis.org/A141326
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = 9*n^4 + 3*n
 * Range:     u8 n <= 2, u16 n <= 9, u32 n <= 147, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* offset: a(1) is the first term */
    if (n == (idx_t)0)
        return (seq_t)0;      /* value for n=0 is irrelevant */

    seq_t nn  = (seq_t)n;
    seq_t n2  = nn * nn;      /* n^2 */
    seq_t n4  = n2 * n2;      /* n^4 */
    seq_t res = 9 * n4 + 3 * nn;   /* 9*n^4 + 3*n */
    return res;
}
